from __future__ import annotations

import os


DEFAULT_ROS_NAMESPACE = "tj"


def ros_namespace() -> str:
    """Return the configured namespace without leading/trailing slashes."""
    # Both launch graphs now expose the apex_ros_namespace argument (default
    # "tj"), so the whole Apex graph shares one namespace.
    return os.environ.get("APEX_ROS_NAMESPACE", DEFAULT_ROS_NAMESPACE).strip().strip("/")


def ros_name(name: str, namespace: str | None = None) -> str:
    """Resolve a logical ROS name under the configured Apex namespace."""
    clean_name = name.strip().strip("/")
    clean_namespace = ros_namespace() if namespace is None else namespace.strip().strip("/")
    if not clean_name:
        return f"/{clean_namespace}" if clean_namespace else "/"
    if not clean_namespace:
        return f"/{clean_name}"
    if clean_name == clean_namespace or clean_name.startswith(f"{clean_namespace}/"):
        return f"/{clean_name}"
    return f"/{clean_namespace}/{clean_name}"


def public_ros_name(name: str, namespace: str | None = None) -> str:
    """Return the stable, root-style ROS name exposed to frontend clients."""
    normalized = f"/{name.strip().strip('/')}"
    clean_namespace = ros_namespace() if namespace is None else namespace.strip().strip("/")
    if not clean_namespace:
        return normalized
    namespace_prefix = f"/{clean_namespace}"
    if normalized == namespace_prefix:
        return "/"
    if normalized.startswith(f"{namespace_prefix}/"):
        return normalized[len(namespace_prefix):]
    return normalized
